function knapsack(wt, val, W) {
  const memo = Array.from({ length: wt.length + 1 }, () => Array(W + 1).fill(-1));
  function go(i, w) {
    if (i === wt.length || w === 0) return 0;
    if (memo[i][w] !== -1) return memo[i][w];
    let best = go(i + 1, w);
    if (wt[i] <= w) best = Math.max(best, val[i] + go(i + 1, w - wt[i]));
    return memo[i][w] = best;
  }
  return go(0, W);
}
